function escapeHtml(s=''){ return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }

function signedPct(value){const n=Number(value)||0;const sign=n>0?'+':n<0?'−':'';return `${sign}${Math.abs(n).toFixed(1)}%`;}
