function dateFilterBounds(){
  const f=state.invoiceDateFilter||{preset:'all',from:'',to:''};
  const now=new Date();
  const y=now.getFullYear(),m=now.getMonth();
  const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  let from='',to='';
  if(f.preset==='this_year'){from=`${y}-01-01`;to=`${y}-12-31`;}
  else if(f.preset==='last_year'){from=`${y-1}-01-01`;to=`${y-1}-12-31`;}
  else if(f.preset==='this_month'){from=iso(new Date(y,m,1));to=iso(new Date(y,m+1,0));}
  else if(f.preset==='last_month'){from=iso(new Date(y,m-1,1));to=iso(new Date(y,m,0));}
  else if(f.preset==='this_quarter'){const q=Math.floor(m/3)*3;from=iso(new Date(y,q,1));to=iso(new Date(y,q+3,0));}
  else if(f.preset==='last_quarter'){let q=Math.floor(m/3)*3-3,yy=y;if(q<0){q+=12;yy-=1;}from=iso(new Date(yy,q,1));to=iso(new Date(yy,q+3,0));}
  else if(f.preset==='custom'){from=f.from||'';to=f.to||'';}
  return {from,to};
}
function priorComparableBounds(){
  const p=state.invoiceDateFilter?.preset||'all';if(p==='all'||p==='custom')return null;
  const now=new Date(),y=now.getFullYear(),m=now.getMonth(),d=now.getDate();
  const iso=x=>`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;
  if(p==='this_year')return {from:`${y-1}-01-01`,to:iso(new Date(y-1,m,d)),label:`Same period ${y-1}`};
  if(p==='last_year')return {from:`${y-2}-01-01`,to:`${y-2}-12-31`,label:String(y-2)};
  if(p==='this_month')return {from:iso(new Date(y-1,m,1)),to:iso(new Date(y-1,m,d)),label:`Same month-to-date ${y-1}`};
  if(p==='last_month'){const lm=new Date(y,m-1,1);return {from:iso(new Date(lm.getFullYear()-1,lm.getMonth(),1)),to:iso(new Date(lm.getFullYear()-1,lm.getMonth()+1,0)),label:'Same month prior year'};}
  if(p==='this_quarter'){const q=Math.floor(m/3)*3;const elapsed=Math.floor((now-new Date(y,q,1))/86400000);const ps=new Date(y-1,q,1),pe=new Date(ps);pe.setDate(pe.getDate()+elapsed);return {from:iso(ps),to:iso(pe),label:'Same quarter-to-date prior year'};}
  if(p==='last_quarter'){let q=Math.floor(m/3)*3-3,yy=y;if(q<0){q+=12;yy--;}return {from:iso(new Date(yy-1,q,1)),to:iso(new Date(yy-1,q+3,0)),label:'Same quarter prior year'};}
  return null;
}
