function productRelationship(history=[]){const groups=[...new Set(history.map(r=>r.equivalentGroup).filter(Boolean))];const proposal=state.equivalenceProposals.find(p=>p.productKeys?.some(k=>history.some(r=>r.key===k))&&p.status!=='rejected');if(proposal&&!groups.includes(proposal.groupId))groups.push(proposal.groupId);let approved=false,rejected=false,awaiting=false,possible=false;for(const group of groups){const d=decisionFor(group),p=equivalenceProposalFor(group);if(d?.status==='approved'||p?.status==='approved')approved=true;else if(d?.status==='rejected'||p?.status==='rejected')rejected=true;else {possible=true;if(state.reviewAssignments?.[group]||p?.status==='pending')awaiting=true;}}if(approved)return {code:'approved',label:'Approved equivalent'};if(possible&&awaiting)return {code:'awaiting',label:'Possible equivalent · awaiting review'};if(possible)return {code:'possible',label:'Possible equivalent'};if(rejected)return {code:'rejected',label:'Not equivalent'};return {code:'independent',label:'No equivalence relationship'};}
