function compactDecisionStatus(d){if(!d)return '';const latest=[...(d.history||[])].slice(-1)[0]||{};const source=latest.source||d.source||'',notes=latest.notes||d.notes||'';return `<div class="compact-decision"><strong>${escapeHtml(decisionLabel(d))}</strong><div>${escapeHtml(d.decidedByName||'')} · ${escapeHtml(d.updatedAt?new Date(d.updatedAt).toLocaleString():'')}</div>${source?`<div><strong>Source:</strong> ${escapeHtml(source)}</div>`:''}${notes?`<div><strong>Notes:</strong> ${escapeHtml(notes)}</div>`:''}${d.history?.length?`<div class="metric-note">${d.history.length} recorded history event${d.history.length===1?'':'s'}</div>`:''}</div>`;}
