async function assignGroups(findings,assigneeUserId,notes=''){const assignee=demoUsers.find(u=>u.id===assigneeUserId);if(!assignee)throw new Error('Unknown review assignee.');if(!findings.every(f=>assignee.permissions.includes(f.requiredPermission)))throw new Error('Selected assignee is not authorized for every selected review.');const me=currentUser(),at=new Date().toISOString();for(const f of findings){const prior=assignmentFor(f.equivalentGroup);const history=[...(prior?.history||[]),{action:prior?.assigneeUserId&&prior.assigneeUserId!==assigneeUserId?'reassigned':'assigned',assigneeUserId,assigneeName:assignee.name,byUserId:me.id,byName:me.name,byRole:me.role,at,notes}];state.reviewAssignments[f.equivalentGroup]={assigneeUserId,assignedByUserId:me.id,assignedByName:me.name,assignedByRole:me.role,assignedAt:at,history};}await persistIfNeeded();}
function decisionLabel(d){return d?.status==='approved'?'Approved as purchasing equivalent':d?.status==='rejected'?'Not equivalent':d?.status==='reopened'?'Reopened for review':'Pending review';}
function decisionHistoryHtml(d){if(!d?.history?.length)return '';return `<div class="decision-history">${d.history.slice().reverse().map(h=>{const base=h.status==='approved'?'Approved as purchasing equivalent':h.status==='rejected'?'Not equivalent':h.status==='reopened'?'Reopened for review':'Decision updated';const label=h.action==='override'?`Override: ${base}`:base;return `<div class="decision-entry"><strong>${escapeHtml(label)}</strong><br>${escapeHtml(h.byName||'')} · ${escapeHtml(h.byRole||'')} · ${escapeHtml(h.at?new Date(h.at).toLocaleString():'')}${h.previousStatus?`<br>Previous decision: ${escapeHtml(h.previousStatus)}`:''}${h.source?`<br>Source: ${escapeHtml(h.source)}`:''}${h.notes?`<br>Notes: ${escapeHtml(h.notes)}`:''}</div>`}).join('')}</div>`;}

function opportunityCard(f){return `<article class="opportunity-card"><div><div class="eyebrow">${escapeHtml(f.type)}</div><h3>${escapeHtml(f.title)}</h3><p>${escapeHtml(f.summary)}</p><span class="confidence ${f.confidence.toLowerCase()}">${f.confidence}</span><div style="margin-top:12px"><button class="link-button" data-finding="${escapeHtml(f.id)}">See calculation →</button></div></div><div class="opportunity-amount">${fmtMoney(f.amount)}<div class="metric-note">${escapeHtml(f.amountLabel||'potential annualized opportunity')}</div></div></article>`}
function bars(items,total,kind=''){
  const max=Math.max(...items.map(x=>x[1]),1);
  return `<div class="bar-list">${items.slice(0,7).map(([k,v])=>{
    const attrs=kind==='vendor'?`data-overview-vendor="${escapeHtml(k)}"`:kind==='category'?`data-overview-category="${escapeHtml(k)}"`:'';
    const cls=attrs?'bar-row bar-row-button':'bar-row';
    const open=attrs?`<button type="button" class="${cls}" ${attrs}>`:`<div class="${cls}">`;
    const close=attrs?'</button>':'</div>';
    return `${open}<div>${escapeHtml(k)}</div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(4,v/max*100)}%"></div></div><div class="bar-value">${fmtMoney(v)} <span class="metric-note">${fmtPct(v/Math.max(total,1)*100)}</span></div>${close}`;
  }).join('')}</div>`;
}

